	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	nowFn    func() time.Time
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is like New but accepts a custom Clock.
func NewWithClock(rate float64, burst int, c Clock) (*Limiter, error) {
	if c == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	now := c.Now()
	return &Limiter{
		rate:  rate,
		burst: burst,
		tokens: float64(burst),
		last:  now,
		nowFn: c.Now,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, refilling the bucket
// based on elapsed time. It consumes tokens only if allowed.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.nowFn()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.nowFn()
	elapsed := now.Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > float64(l.burst) {
		t = float64(l.burst)
	}
	return t
}
