	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.last.IsZero() {
		elapsed := l.clock.Now().Sub(l.last).Seconds()
		t := l.tokens + elapsed*l.rate
		if t > l.capacity {
			t = l.capacity
		}
		return t
	}
	return l.tokens
