	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It allows bursts up to Burst and refills tokens at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    int
	maxTok   float64
	nowFn    func() time.Time
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
)

// New creates a Limiter with the given refill rate (tokens/sec) and burst size.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is like New but accepts a custom Clock (useful in tests).
func NewWithClock(rate float64, burst int, c Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if c == nil {
		c = realClock{}
	}
	now := c.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		rate:   rate,
		burst:  burst,
		maxTok: float64(burst),
		nowFn:  c.Now,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.nowFn()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.maxTok {
			l.tokens = l.maxTok
		}
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// RetryAfter returns the duration until n tokens would become available.
// It returns 0 if n tokens are available now.
func (l *Limiter) RetryAfter(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.nowFn()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.maxTok {
			l.tokens = l.maxTok
		}
		l.last = now
	}
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
